select pg.project_group_id, pg.project_id, pg.group_id, g.group_name, g.gender, g.description, g.reasons, g.dosage from tb_project_group pg left join tb_group g on pg.group_id = g.group_id where pg.del_flag = '0' AND pg.project_id in
#{projectId}
AND g.group_name LIKE CONCAT('%',#{groupName},'%')
AND g.reasons = #{reasons}

